import { env, sessionSecret } from "@/lib/env";
import { hmacHex, randomToken, safeEqual } from "@/lib/crypto";
import { apiPath } from "@/lib/paths";

/**
 * Recorded-video adapters.
 *  - cloudflare: Cloudflare Stream direct creator uploads, requireSignedURLs, short-lived playback tokens.
 *  - local:      development storage on disk (storage/videos) served through an HMAC-signed,
 *                user-bound, expiring URL with HTTP Range support. NOT for production.
 *  - sample:     small synthetic demo clips bundled in storage/sample (generated by scripts/generate-sample-media.sh).
 */
export type VideoProviderName = "cloudflare" | "local" | "sample";

export interface UploadTicket {
  providerUid: string;
  uploadUrl: string;
  method: "POST_FORM" | "PUT_BINARY";
}

export interface Playback {
  kind: "iframe" | "file";
  src: string;
  expiresAt: number;
}

const PLAYBACK_TTL = 60 * 10; // 10 minutes

// ── signed local media URLs ────────────────────────────────────────────────
export function signMediaUrl(assetId: string, userId: string, ttl = PLAYBACK_TTL): { url: string; exp: number } {
  const exp = Math.floor(Date.now() / 1000) + ttl;
  const sig = hmacHex(sessionSecret(), `media:${assetId}:${userId}:${exp}`);
  return { url: apiPath(`/media/video/${assetId}?u=${userId}&exp=${exp}&sig=${sig}`), exp };
}

export function verifyMediaSignature(assetId: string, userId: string, exp: number, sig: string): boolean {
  if (!exp || exp < Math.floor(Date.now() / 1000)) return false;
  return safeEqual(hmacHex(sessionSecret(), `media:${assetId}:${userId}:${exp}`), sig);
}

export function signUploadToken(assetId: string, userId: string, ttl = 60 * 60): string {
  const exp = Math.floor(Date.now() / 1000) + ttl;
  return `${exp}.${hmacHex(sessionSecret(), `upload:${assetId}:${userId}:${exp}`)}`;
}

export function verifyUploadToken(assetId: string, userId: string, token: string): boolean {
  const [expStr, sig] = token.split(".");
  const exp = Number(expStr);
  if (!exp || exp < Math.floor(Date.now() / 1000) || !sig) return false;
  return safeEqual(hmacHex(sessionSecret(), `upload:${assetId}:${userId}:${exp}`), sig);
}

// ── Cloudflare Stream ──────────────────────────────────────────────────────
async function cf(path: string, init: RequestInit = {}) {
  const e = env();
  if (!e.CLOUDFLARE_ACCOUNT_ID || !e.CLOUDFLARE_STREAM_API_TOKEN) throw new Error("Cloudflare Stream is not configured.");
  const res = await fetch(`https://api.cloudflare.com/client/v4/accounts/${e.CLOUDFLARE_ACCOUNT_ID}/stream${path}`, {
    ...init,
    headers: { Authorization: `Bearer ${e.CLOUDFLARE_STREAM_API_TOKEN}`, "Content-Type": "application/json", ...(init.headers || {}) },
    cache: "no-store",
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || data.success === false) throw new Error(`Cloudflare Stream ${path}: ${data?.errors?.[0]?.message || res.status}`);
  return data.result;
}

export async function createUploadTicket(assetId: string, userId: string, maxDurationSeconds = 4 * 3600): Promise<UploadTicket> {
  if (env().VIDEO_PROVIDER === "cloudflare") {
    const r = await cf("/direct_upload", {
      method: "POST",
      body: JSON.stringify({ maxDurationSeconds, requireSignedURLs: true, meta: { assetId, uploadedBy: userId } }),
    });
    return { providerUid: r.uid, uploadUrl: r.uploadURL, method: "POST_FORM" };
  }
  const uid = `local_${randomToken(12)}`;
  return { providerUid: uid, uploadUrl: apiPath(`/videos/upload/${assetId}?token=${signUploadToken(assetId, userId)}`), method: "PUT_BINARY" };
}

export async function getCloudflareStatus(uid: string) {
  const v = await cf(`/${encodeURIComponent(uid)}`);
  const state: string = v?.status?.state ?? "inprogress";
  return {
    status: state === "ready" ? ("READY" as const) : state === "error" ? ("ERROR" as const) : ("PROCESSING" as const),
    durationSeconds: v?.duration > 0 ? Math.round(v.duration) : null,
    thumbnailUrl: v?.thumbnail ?? null,
    error: v?.status?.errorReasonText ?? null,
  };
}

export async function playbackFor(asset: { id: string; provider: VideoProviderName; provider_uid: string }, userId: string): Promise<Playback> {
  if (asset.provider === "cloudflare") {
    const exp = Math.floor(Date.now() / 1000) + PLAYBACK_TTL;
    const r = await cf(`/${encodeURIComponent(asset.provider_uid)}/token`, { method: "POST", body: JSON.stringify({ exp }) });
    const code = env().CLOUDFLARE_STREAM_CUSTOMER_CODE;
    const host = code ? `https://customer-${code}.cloudflarestream.com` : "https://iframe.videodelivery.net";
    return { kind: "iframe", src: code ? `${host}/${r.token}/iframe` : `${host}/${r.token}`, expiresAt: exp };
  }
  const { url, exp } = signMediaUrl(asset.id, userId);
  return { kind: "file", src: url, expiresAt: exp };
}

export async function deleteRemoteVideo(provider: VideoProviderName, uid: string) {
  if (provider === "cloudflare") await cf(`/${encodeURIComponent(uid)}`, { method: "DELETE" });
}

/** Cloudflare webhook: header "Webhook-Signature: time=<unix>,sig1=<hex hmac(time.body)>" */
export function verifyCloudflareWebhook(rawBody: string, header: string | null): boolean {
  const secret = env().CLOUDFLARE_STREAM_WEBHOOK_SECRET;
  if (!header || !secret) return false;
  const parts = Object.fromEntries(header.split(",").map((kv) => kv.split("=") as [string, string]));
  const time = Number(parts.time);
  if (!time || Math.abs(Date.now() / 1000 - time) > 300) return false;
  return safeEqual(hmacHex(secret, `${parts.time}.${rawBody}`), parts.sig1 ?? "");
}
